// ===== extracted inline script 35; id=v3-3-ux-ru-label-tests =====
(function () {
    'use strict';
    function hasRawTechLabel(s) {
        return /^[a-z]+[a-z0-9_\-\/ &]*$/.test(String(s || '').trim()) && /[a-z]/.test(String(s || ''));
    }
    window.runUxRuLabelTests = function () {
        var labels = window.UI_RU_LABELS || {};
        var db = window.DB || {};
        var items = Array.isArray(db.items) ? db.items : [];
        var heiKeys = Array.from(new Set(items.map(function (p) { return p.hei_category_key || 'other'; })));
        var catalogKeys = Array.from(new Set(items.map(function (p) { return p.catalog_category_key || 'other'; })));
        var badHei = heiKeys.filter(function (k) { return hasRawTechLabel(labels.labelHEI ? labels.labelHEI(k) : k); });
        var badCat = catalogKeys.filter(function (k) { return hasRawTechLabel(labels.labelCatalog ? labels.labelCatalog(k) : k); });
        var results = [
            { test: 'UX: HEI labels do not expose raw keys', pass: badHei.length === 0, got: badHei, expected: [] },
            { test: 'UX: catalog labels do not expose raw keys', pass: badCat.length === 0, got: badCat, expected: [] },
            { test: 'UX: vegetables label exists', pass: (labels.labelHEI && labels.labelHEI('vegetables') === 'Овощи'), got: labels.labelHEI && labels.labelHEI('vegetables'), expected: 'Овощи' },
            { test: 'UX: fruits label exists', pass: (labels.labelHEI && labels.labelHEI('fruits') === 'Фрукты'), got: labels.labelHEI && labels.labelHEI('fruits'), expected: 'Фрукты' }
        ];
        console.table(results);
        return results.every(function (r) { return !!r.pass; });
    };
    var prevSmoke = window.runSmokeTests;
    window.runSmokeTests = function () {
        var base = prevSmoke ? prevSmoke() : true;
        var ux = window.runUxRuLabelTests ? window.runUxRuLabelTests() : false;
        return !!base && !!ux;
    };
})();
;
